import dev.pocketllama.photo.*;
import android.content.Context;
import java.io.*;
import java.nio.file.*;
import java.util.*;
import org.json.*;

public final class SuryaPipelineTests {
 static int checks;static void ok(boolean v,String name){if(!v)throw new AssertionError(name);checks++;}
 static String block(String label,String bbox,String html){return "<div data-label='"+label+"' data-bbox='"+bbox+"'>"+html+"</div>";}
 static final String FIRST=block("Text","0 0 1000 300","<p>Сохранённый текст 125 480 рублей</p>");
 static final String TABLE=block("Table","0 300 1000 900","<table><tr><th colspan=2>Счёт</th></tr><tr><td>Бумага</td><td>500</td></tr></table>");
 static String page(PhotoStore photos)throws Exception{return photos.create(new byte[]{1,2},new byte[]{3},900,1200);}
 public static void main(String[] args)throws Exception {
  Path root=Files.createTempDirectory("surya-pipeline");Context c=new Context(root.toFile());PhotoStore photos=new PhotoStore(c);File model=new File("surya-2.gguf");List<String> phases=new ArrayList<>(),messages=new ArrayList<>();final String[] latest={""};final Map<String,Long> origins=new HashMap<>();
  SuryaPipeline.Progress progress=new SuryaPipeline.Progress(){public void update(String s,double f){latest[0]=s;messages.add(s);}public void phase(String phase,String s,double f,long since){if(phase.equals("page"))origins.clear();if(origins.containsKey(phase))ok(origins.get(phase)==since,"one origin for repeated input progress");else origins.put(phase,since);phases.add(phase);update(s,f);}};
  String p1=page(photos),p2=page(photos);SuryaRuntime.reset();SuryaRuntime.reply(FIRST+TABLE);SuryaRuntime.reply(FIRST);SuryaRuntime.beforeRequest=()->ok(latest[0].equals("Подготавливаем изображение"),"document leaves loading before any request/first text, including warm page two");SuryaRuntime.onInput=()->ok(latest[0].contains("50% подготовки"),"native preparation progress reaches the document before first text");
  try(SuryaPipeline pipeline=new SuryaPipeline(c,photos,()->{})){pipeline.page(p1,model,progress);pipeline.page(p2,model,progress);ok(SuryaRuntime.loads==1&&SuryaRuntime.closes==0,"one loaded VLM for two pages");}
  ok(SuryaRuntime.closes==1&&SuryaRuntime.calls.equals(Arrays.asList(SuryaImageSize.Task.PAGE,SuryaImageSize.Task.PAGE)),"one request per page and one shutdown");ok(SuryaDetector.calls==0,"ordinary OCR never runs the independent detector");
  ok(messages.stream().filter(s->s.equals("Загружаем Surya OCR 2")).count()==1,"one model load status across two pages");ok(!photos.get(p1).getJSONObject("analysis").getJSONObject("performance").getBoolean("runtime_reused")&&photos.get(p2).getJSONObject("analysis").getJSONObject("performance").getBoolean("runtime_reused"),"stored timing distinguishes a cold load from warm page two");
  JSONObject first=photos.get(p1);ok(first.getString("state").equals("done")&&first.getString("text").contains("Бумага"),"full-page text committed");ok(first.getJSONObject("analysis").getJSONArray("blocks").getJSONObject(1).getJSONArray("tables").getJSONObject(0).getJSONArray("cells").getJSONObject(0).getInt("colspan")==2,"full-page merged table retained");
  JSONObject legacy=first.getJSONObject("analysis");JSONObject unfinished=legacy.getJSONArray("blocks").getJSONObject(1);unfinished.put("complete",false);unfinished.remove("text");unfinished.remove("html");unfinished.remove("tables");photos.analysis(p1,"interrupted","legacy",.3,legacy);
  SuryaRuntime.reset();SuryaRuntime.reply("<table><tr><td>Бумага</td><td>500</td></tr></table>");try(SuryaPipeline pipeline=new SuryaPipeline(c,photos,()->{})){pipeline.page(p1,model,progress);}
  ok(SuryaRuntime.calls.equals(Arrays.asList(SuryaImageSize.Task.BLOCK)),"legacy resume recognizes only the unfinished block");ok(photos.get(p1).getString("text").contains("Сохранённый текст"),"legacy completed text retained");
  photos.edit(p2,"Ручная правка пользователя");String oldLines=photos.get(p2).getJSONArray("lines").toString();SuryaRuntime.reset();try(SuryaPipeline pipeline=new SuryaPipeline(c,photos,()->{})){pipeline.details(p2,model,progress);}
  JSONObject refined=photos.get(p2);ok(SuryaDetector.calls==1&&SuryaRuntime.loads==0,"line-only enrichment avoids loading a VLM");ok(refined.getBoolean("edited")&&refined.getString("text").equals("Ручная правка пользователя")&&refined.getJSONArray("lines").toString().equals(oldLines),"geometry preserves manual text and source lines");ok(refined.getJSONObject("analysis").getBoolean("geometryComplete"),"geometry completion saved");
  photos.edit(p1,"Исправленная сумма 501");SuryaRuntime.reset();SuryaRuntime.reply("[{\"label\":\"Row\",\"bbox\":\"0 0 1000 1000\"},{\"label\":\"Col\",\"bbox\":\"0 0 1000 1000\"}]");try(SuryaPipeline pipeline=new SuryaPipeline(c,photos,()->{})){pipeline.details(p1,model,progress);}
  ok(SuryaRuntime.calls.equals(Arrays.asList(SuryaImageSize.Task.TABLE))&&SuryaDetector.calls==1,"table geometry is a separate explicit operation");ok(photos.get(p1).getBoolean("edited")&&photos.get(p1).getString("text").equals("Исправленная сумма 501"),"table enrichment preserves edits");
  String p3=page(photos);SuryaRuntime.reset();SuryaRuntime.fail(FIRST+"<div data-label='Text' data-bbox='0 300 1000 900'>НЕЗАВЕРШЕНО",new IOException("transport EOF"));
  try(SuryaPipeline pipeline=new SuryaPipeline(c,photos,()->{})){try{pipeline.page(p3,model,progress);throw new AssertionError("EOF must interrupt");}catch(IOException expected){}}
  JSONObject partial=photos.get(p3);ok(partial.getString("state").equals("interrupted")&&partial.getJSONObject("analysis").getBoolean("pagePending"),"EOF never marks a partial page complete");ok(partial.getString("text").contains("Сохранённый")&&!partial.getString("text").contains("НЕЗАВЕРШЕНО"),"only explicitly closed HTML blocks become checkpoints");
  String layout="[{\"label\":\"Text\",\"bbox\":\"0 0 1000 300\",\"count\":100},{\"label\":\"Text\",\"bbox\":\"0 300 1000 900\",\"count\":100}]";
  SuryaRuntime.reply(layout);SuryaRuntime.reply("<p>Оставшаяся область</p>");try(SuryaPipeline pipeline=new SuryaPipeline(c,photos,()->{})){pipeline.page(p3,model,progress);}ok(photos.get(p3).getString("state").equals("done")&&SuryaRuntime.calls.equals(Arrays.asList(SuryaImageSize.Task.PAGE,SuryaImageSize.Task.LAYOUT,SuryaImageSize.Task.BLOCK)),"resume switches the unfinished page to remaining blocks without rereading PAGE");
  String p4=page(photos);SuryaRuntime.reset();SuryaRuntime.fail(FIRST+"<div data-label='Text' data-bbox='0 300 1000 900'>",new SuryaRuntime.Incomplete("length"));SuryaRuntime.reply("[{\"label\":\"Text\",\"bbox\":\"0 0 1000 300\",\"count\":100},{\"label\":\"Text\",\"bbox\":\"0 300 1000 900\",\"count\":100}]");SuryaRuntime.reply("<p>Оставшаяся область</p>");
  try(SuryaPipeline pipeline=new SuryaPipeline(c,photos,()->{})){pipeline.page(p4,model,progress);}
  ok(SuryaRuntime.calls.equals(Arrays.asList(SuryaImageSize.Task.PAGE,SuryaImageSize.Task.LAYOUT,SuryaImageSize.Task.BLOCK)),"length fallback reuses matching completed blocks");ok(photos.get(p4).getString("text").equals("Сохранённый текст 125 480 рублей\n\nОставшаяся область"),"fallback retains reading order without duplicated text");
  String p5=page(photos);SuryaRuntime.reset();SuryaRuntime.reply(FIRST+FIRST+FIRST);SuryaRuntime.fail("",new IOException("layout interrupted"));
  try(SuryaPipeline pipeline=new SuryaPipeline(c,photos,()->{})){try{pipeline.page(p5,model,progress);throw new AssertionError("failed layout must interrupt");}catch(IOException expected){}}
  JSONObject loop=photos.get(p5),loopAnalysis=loop.getJSONObject("analysis");ok(loop.getString("state").equals("interrupted")&&loopAnalysis.getBoolean("layoutPending")&&loopAnalysis.getString("fallbackReason").equals("repetition"),"fallback strategy is persisted before a failed layout request");ok(loop.getString("text").equals("Сохранённый текст 125 480 рублей")&&!loopAnalysis.getBoolean("ocrComplete"),"duplicated closed regions are never saved as completed text");
  SuryaRuntime.reply(layout);SuryaRuntime.reply("<p>Продолжение без повторного чтения страницы</p>");try(SuryaPipeline pipeline=new SuryaPipeline(c,photos,()->{})){pipeline.page(p5,model,progress);}
  ok(SuryaRuntime.calls.equals(Arrays.asList(SuryaImageSize.Task.PAGE,SuryaImageSize.Task.LAYOUT,SuryaImageSize.Task.LAYOUT,SuryaImageSize.Task.BLOCK)),"continue after failed fallback never repeats the whole-page generation");ok(photos.get(p5).getString("state").equals("done")&&photos.get(p5).getString("text").contains("Продолжение без повторного"),"resume completes remaining content");
  String p6=page(photos);SuryaRuntime.reset();SuryaRuntime.fail(FIRST,new SuryaRuntime.Incomplete("repetition"));SuryaRuntime.reply(layout);SuryaRuntime.fail("<p>loop",new SuryaRuntime.Incomplete("repetition"));
  try(SuryaPipeline pipeline=new SuryaPipeline(c,photos,()->{})){try{pipeline.page(p6,model,progress);throw new AssertionError("looping block must stay pending");}catch(IOException expected){}}
  ok(SuryaRuntime.calls.size()==3&&SuryaRuntime.steps.isEmpty(),"looping block is not retried automatically with 8192 tokens");ok(photos.get(p6).getString("text").equals("Сохранённый текст 125 480 рублей")&&!photos.get(p6).getJSONObject("analysis").getJSONArray("blocks").getJSONObject(1).getBoolean("complete"),"good text retained and looping block remains pending");
  SuryaRuntime.reply("<p>Восстановленная область</p>");try(SuryaPipeline pipeline=new SuryaPipeline(c,photos,()->{})){pipeline.page(p6,model,progress);}ok(SuryaRuntime.calls.get(3)==SuryaImageSize.Task.BLOCK&&photos.get(p6).getString("state").equals("done"),"resume retries only the unresolved block");
  String p7=page(photos);SuryaRuntime.reset();SuryaRuntime.fail(FIRST,new SuryaRuntime.Incomplete("deadline"));SuryaRuntime.reply(layout);SuryaRuntime.reply("<p>После ограничения времени</p>");try(SuryaPipeline pipeline=new SuryaPipeline(c,photos,()->{})){pipeline.page(p7,model,progress);}ok(photos.get(p7).getString("state").equals("done")&&photos.get(p7).getJSONObject("analysis").getString("fallbackReason").equals("deadline"),"whole-page deadline preserves checkpoints and switches to blocks");
  try(java.util.stream.Stream<Path> paths=Files.walk(root)){paths.sorted(Comparator.reverseOrder()).forEach(p->{try{Files.delete(p);}catch(Exception e){throw new RuntimeException(e);}});}System.out.println("SuryaPipelineTests: "+checks+" checks passed (production pipeline/stores; scripted native transport)");
 }
}
